def next_version(current, changes):
    major, minor, patch = (int(x) for x in current.split("."))
    kinds = set(changes)
    if major >= 1:
        if "breaking" in kinds:
            major, minor, patch = major + 1, 0, 0
        elif "feature" in kinds:
            minor, patch = minor + 1, 0
        elif "fix" in kinds:
            patch += 1
    else:
        if "breaking" in kinds:
            minor, patch = minor + 1, 0
        elif "feature" in kinds or "fix" in kinds:
            patch += 1
    return "%d.%d.%d" % (major, minor, patch)

msvc-contract-verify.solution:
def verify_contracts(contracts, provider):
    def type_of(v):
        if v is None:
            return "null"
        if isinstance(v, bool):
            return "boolean"
        if isinstance(v, int):
            return "integer"
        if isinstance(v, float):
            return "number"
        if isinstance(v, str):
            return "string"
        if isinstance(v, list):
            return "array"
        return "object"

    def check(expected, actual, prefix, out):
        for name in sorted(expected):
            full = prefix + name
            want = expected[name]
            if name not in actual:
                out.append("missing field " + full)
                continue
            got = type_of(actual[name])
            if isinstance(want, dict):
                if got != "object":
                    out.append("field %s is %s, expected object" % (full, got))
                else:
                    check(want, actual[name], full + ".", out)
            elif got != want and not (want == "number" and got == "integer"):
                out.append("field %s is %s, expected %s" % (full, got, want))

    result = []
    for c in contracts:
        key = c["method"] + " " + c["path"]
        if key not in provider:
            result.append([c["consumer"], key, "missing endpoint"])
            continue
        resp = provider[key]
        msgs = []
        if resp["status"] != c["status"]:
            msgs.append("status %d != %d" % (resp["status"], c["status"]))
        check(c["body"], resp["body"], "", msgs)
        for m in msgs:
            result.append([c["consumer"], key, m])
    return result

