            log.append("deployed %s to %s" % (op[1], idle))
        elif kind == "smoke":
            if status[idle] == "empty":
                log.append("nothing to test")
            else:
                status[idle] = "verified" if op[1] else "failed"
                log.append("smoke passed" if op[1] else "smoke failed")
        elif kind == "switch":
            if status[idle] == "verified":
                live, idle = idle, live
                can_rollback = True
                log.append("switched to " + live)
            else:
                log.append("switch refused")
        elif kind == "rollback":
            if can_rollback:
                live, idle = idle, live
                can_rollback = False
                log.append("rolled back to " + live)
            else:
                log.append("rollback refused")
    return {"log": log, "live": live, "live_version": version[live], "idle_version": version[idle]}

msvc-feature-toggle.solution:
def is_enabled(toggle, user):
    if not toggle["enabled"]:
        return False
    for rule in toggle.get("rules", []):
        attr = rule["attr"]
        if attr not in user:
            continue
        have, want, op = user[attr], rule["value"], rule["op"]
        if op == "eq":
            hit = have == want
        elif op == "neq":
            hit = have != want
        elif op == "in":
            hit = have in want
        elif op == "gte":
            hit = have >= want
        elif op == "lt":
            hit = have < want
        else:
            hit = False
        if hit:
            return rule["result"]
    key = toggle["salt"] + ":" + user["id"]
    bucket = sum((i + 1) * ord(ch) for i, ch in enumerate(key)) % 100
    return bucket < toggle["percentage"]

msvc-jwt-confused-deputy.solution:
def authorise_chain(token, now, trust, hops):
    def user_check(hop):
        if not token["exp"] > now:
            return "expired"
        if hop["callee"] not in token["aud"]:
            return "audience"
        if hop["scope"] not in token["scopes"]:
            return "scope"
        if hop["owner"] != token["sub"] and "admin" not in token["scopes"]:
            return "owner"
        return None

    out = []
    stopped = False
    for hop in hops:
        if stopped:
            out.append("skipped")
            continue
        reason = user_check(hop)
        if hop["forward"]:
            if reason is None:
                out.append("allow")
            else:
                out.append("deny:" + reason)
                stopped = True
        elif hop["caller"] not in trust.get(hop["callee"], []):
            out.append("deny:untrusted")
            stopped = True
        else:
            out.append("allow" if reason is None else "confused-deputy")
    return out

msvc-conway-mismatch.solution:
def conway_report(ownership, calls, team_links):
    links = set()
    for a, b in team_links:
        links.add((a, b))
        links.add((b, a))
    same = cross = 0
    mismatches, unowned, pairs = [], set(), {}
    for caller, callee in sorted(set((c[0], c[1]) for c in calls)):
        missing = [s for s in (caller, callee) if s not in ownership]
        if missing:
            unowned.update(missing)
            continue
        ta, tb = ownership[caller], ownership[callee]
        if ta == tb:
            same += 1
            continue
        cross += 1
        key = tuple(sorted((ta, tb)))
        pairs[key] = pairs.get(key, 0) + 1
        if (ta, tb) not in links:
            mismatches.append([caller, callee])
    busiest = None
    if pairs:
        busiest = list(min(pairs, key=lambda k: (-pairs[k], k)))
    return {"same_team": same, "cross_team": cross, "mismatches": mismatches, "unowned": sorted(unowned), "busiest_pair": busiest}

msvc-monorepo-affected.solution:
def affected_projects(roots, deps, changed, global_paths):
    def inside(path, directory):
        return path == directory or path.startswith(directory + "/")

    for path in changed:
        if any(inside(path, g) for g in global_paths):
            return sorted(roots)
    direct = set()
    for path in changed:
        best, owner = -1, None
        for name, root in roots.items():
            if inside(path, root) and len(root) > best:
                best, owner = len(root), name
        if owner is not None:
            direct.add(owner)
    users = {}
    for name, ds in deps.items():
        for d in ds:
            users.setdefault(d, []).append(name)
    affected = set(direct)
    stack = list(direct)
    while stack:
        p = stack.pop()
        for u in users.get(p, []):
            if u not in affected and u in roots:
                affected.add(u)
                stack.append(u)
    return sorted(affected)

msvc-bff-aggregate.solution:
def compose_screen(spec, responses, budget_ms):
    called = []
    for part in spec:
        if part[1] not in called:
            called.append(part[1])

    def succeeded(service):
        r = responses.get(service)
        return r is not None and r[0] == "ok" and r[1] <= budget_ms

    elapsed = 0
    for service in called:
        r = responses.get(service)
        if r is not None:
            elapsed = max(elapsed, min(r[1], budget_ms))

    data, missing, fatal = {}, [], False
    for name, service, fields, required in spec:
        if succeeded(service):
            body = responses[service][2]
            data[name] = {f: body.get(f) for f in fields}
        else:
            data[name] = None
            missing.append(name)
            if required:
                fatal = True
    if fatal:
        return {"status": "error", "elapsed_ms": elapsed, "data": {}, "missing": missing}
    return {"status": "degraded" if missing else "ok", "elapsed_ms": elapsed, "data": data, "missing": missing}

msvc-fitness-functions.solution:
def architecture_fitness(calls, layers, max_fan_out):
    graph = {}
    for a, b in calls:
        graph.setdefault(a, set()).add(b)
        graph.setdefault(b, set())

    def reaches_itself(start):
        stack, seen = list(graph[start]), set()
        while stack:
            node = stack.pop()
            if node == start:
                return True
            if node in seen:
                continue
            seen.add(node)
            stack.extend(graph[node])
        return False

    cycles = sorted(s for s in graph if reaches_itself(s))
    fan_out = sorted(s for s, callees in graph.items() if len(callees) > max_fan_out)
    violations = [list(pair) for pair in sorted({(a, b) for a, b in calls if layers[b] < layers[a]})]
    return {"cycles": cycles, "fan_out": fan_out, "layer_violations": violations,
            "passed": not (cycles or fan_out or violations)}

msvc-design-review.solution:
def review_design(services, calls, max_sync_depth):
    findings = set()
    by_db = {}
    for name, info in services.items():
        if not info.get("team"):
            findings.add(("orphan-service", name))
        if info.get("db"):
            by_db.setdefault(info["db"], []).append(name)
    for db, users in by_db.items():
        if len(users) > 1:
            findings.add(("shared-database", db))

    sync = {}
    for caller, callee, mode, timeout_ms, retries, idempotent in calls:
        edge = caller + "->" + callee
        if mode == "sync":
            sync.setdefault(caller, set()).add(callee)
            sync.setdefault(callee, set())
            if timeout_ms is None:
                findings.add(("no-timeout", edge))
        if retries > 0 and not idempotent:
            findings.add(("unsafe-retry", edge))

    def reaches_itself(start):
        stack, seen = list(sync[start]), set()
        while stack:
            node = stack.pop()
            if node == start:
                return True
            if node in seen:
                continue
            seen.add(node)
            stack.extend(sync[node])
        return False

    on_cycle = [s for s in sync if reaches_itself(s)]
    if on_cycle:
        for s in on_cycle:
            findings.add(("sync-cycle", s))
    else:
        depth = {}

        def longest(node):
            if node not in depth:
                depth[node] = max((1 + longest(c) for c in sync[node]), default=0)
            return depth[node]

        deepest = max((longest(s) for s in sync), default=0)
        if deepest > max_sync_depth:
            findings.add(("long-sync-chain", str(deepest)))
    return [list(f) for f in sorted(findings)]
